function toNum(v){
  if (v === null || v === undefined || v === '' || v === '—') return null;
  if (typeof v === 'number') return v;
  var s = String(v).trim();
  if (s === '—' || s === '') return null;
  var n = parseFloat(s.replace(/\s/g,'').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function fmtUAH(v){ if (v===null||v===undefined) return '—'; return Math.round(v).toLocaleString('uk-UA') + 'грн'; }
function fmtPct(v){ if (v===null||v===undefined) return '—'; return (v>0?'+':'') + v.toFixed(v===Math.round(v)?0:1).replace('.',',') + '%'; }
function fmtRatio(v){ if (v===null||v===undefined) return '—'; return v.toFixed(2).replace('.', ','); }

const rows = $input.all().map(function(i){ return i.json; });
const projects = [];
rows.forEach(function(row){
  var id = String(row['ProjectID'] || '').trim();
  if (!id) return;
  var rentForecastRaw = toNum(row['Рентабельність_прогноз_pct']);
  if (rentForecastRaw === null) return;
  var etcPlanTotal = [toNum(row['МБР_ETC_план_год']), toNum(row['ЕП_ETC_план_год']), toNum(row['П_ETC_план_год']), toNum(row['Р_ETC_план_год']), toNum(row['АН_ETC_план_год'])]
    .reduce(function(s,v){ return s + (v||0); }, 0);
  projects.push({
    id: id, name: row['Назва'] || id,
    contract: toNum(row['Контракт']),
    planHrs: toNum(row['Планові_години']),
    factHrs: toNum(row['Фактичний_час']),
    ostHrs: toNum(row['Залишок_часу']),
    etcHrs: toNum(row['ETC_прогноз_всього_год']),
    etcPlanTotal: etcPlanTotal,
    pctVykon: toNum(row['ПроцентВиконання']) !== null ? toNum(row['ПроцентВиконання']) * 100 : null,
    prybutokPlan: toNum(row['Прибуток_план']),
    prybutokForecast: toNum(row['Прибуток_прогноз']),
    rentPlan: toNum(row['Рентабельність_план_pct']) !== null ? toNum(row['Рентабельність_план_pct']) * 100 : null,
    rentForecast: rentForecastRaw * 100,
    rawQ: toNum(row["Засвоєний_об'єм"]),
    rawS: toNum(row['Сума_Актів']),
    rawP: toNum(row['Отримані_гроші']),
    cpi: toNum(row['CPI_класичний_EVM'])
  });
});

const lines = projects.map(function(p){
  var emoji = p.rentForecast < 0 ? '🔴' : (p.rentForecast < 15 ? '🟡' : '🟢');
  var l1 = emoji + ' <b>' + p.name + '</b> (' + p.id + ')';
  var l2 = '⏱ Залишок_план:' + (p.planHrs!==null?p.planHrs+'г':'—') + ' Факт_годин:' + (p.factHrs!==null?p.factHrs+'г':'—') + ' Залишок_факт:' + (p.ostHrs!==null?p.ostHrs+'г':'—') + ' Залишок_прогноз:' + (p.etcHrs!==null?Math.round(p.etcHrs*10)/10+'г':'—') + ' (Залишок_план_всього ' + Math.round(p.etcPlanTotal*10)/10 + 'г)';
  var l3 = '✅ Виконано: ' + (p.pctVykon!==null?(Math.round(p.pctVykon*10)/10)+'%':'—');
  var l4 = '💰 Прибуток_план→Прибуток_прогноз: ' + fmtUAH(p.prybutokPlan) + ' → ' + fmtUAH(p.prybutokForecast) + '  📈 Рентабельність_план→Рентабельність_прогноз: ' + fmtPct(p.rentPlan) + ' → ' + fmtPct(p.rentForecast);
  var l5 = '📦 Засвоєно:' + fmtUAH(p.rawQ) + ' Акти:' + fmtUAH(p.rawS) + ' Оплачено:' + fmtUAH(p.rawP) + '  CPI:' + fmtRatio(p.cpi);
  return [l1,l2,l3,l4,l5].join(String.fromCharCode(10));
}).join(String.fromCharCode(10,10));

const text = $('Telegram Trigger').item.json.message?.text || '';

const system = 'Ти — стратегічний COO-радник власника архітектурного бізнесу (Archi). Відповідаєш українською мовою на рівні операційного директора.' + String.fromCharCode(10) +
'Дані живі — читаються напряму з DEMO_M0.2_AllProjects_Flat при кожному запиті, ' + projects.length + ' проєктів.' + String.fromCharCode(10,10) +
'ДАНІ ПО ПРОЄКТАХ:' + String.fromCharCode(10,10) +
lines + String.fromCharCode(10,10) +
'НОРМАТИВИ:' + String.fromCharCode(10) +
'- Рентабельність: норма ~25%.' + String.fromCharCode(10) +
'- CPI (Cost Performance Index): <0.85 — критична перевитрата; 0.85-1.15 — норма; >1.15 — економія.' + String.fromCharCode(10) +
'- Розрив обсягів: якщо Засвоєно суттєво більше за Акти або Оплачено — компанія кредитує клієнта власним коштом, це касовий ризик.' + String.fromCharCode(10) +
'- Розрив залишку: якщо Залишок_прогноз суттєво більший за Залишок_план_всього — темп витрат випереджає план, ризик перевищення бюджету годин.' + String.fromCharCode(10,10) +
'ГЛОСАРІЙ ПОКАЗНИКІВ (СУВОРО, без винятків):' + String.fromCharCode(10) +
'Кожен показник має РІВНО ОДНУ базову назву і завжди вживається лише з суфіксами _план / _факт / _прогноз. Заборонено вигадувати нові назви, синоніми чи альтернативні формулювання для існуючих показників — навіть якщо питання користувача сформульоване інакше.' + String.fromCharCode(10) +
'Дозволені базові назви показників і ЛИШЕ вони:' + String.fromCharCode(10) +
'- Контракт (сума договору, без план/факт/прогноз)' + String.fromCharCode(10) +
'- Залишок_план, Залишок_факт, Залишок_прогноз (години; "Залишок_прогноз" — це те, що раніше могло називатись ETC чи "реальний темп" — використовуй ТІЛЬКИ "Залишок_прогноз")' + String.fromCharCode(10) +
'- Прибуток_план, Прибуток_прогноз' + String.fromCharCode(10) +
'- Рентабельність_план, Рентабельність_прогноз' + String.fromCharCode(10) +
'- Засвоєно, Акти, Оплачено (грошові суми, без план/факт/прогноз)' + String.fromCharCode(10) +
'- CPI (коефіцієнт, без план/факт/прогноз)' + String.fromCharCode(10) +
'Якщо для відповіді на питання власника не вистачає показника з цього переліку — скажи прямо, що даних немає, НЕ вигадуй нову метрику і НЕ давай їй власну назву.' + String.fromCharCode(10,10) +
'ПРАВИЛА:' + String.fromCharCode(10) +
'1. Якщо проекту немає у списку вище — чесно скажи, що він не в перевіреному наборі, НЕ вигадуй дані.' + String.fromCharCode(10) +
'2. МАКСИМУМ 3 проекти з повним Insight-Impact-Action в одній відповіді (Telegram-повідомлення обмежене 4096 символами — більше фізично не влізе). Якщо запитали конкретні проекти і їх більше 3 — обери 3 найкритичніші з названих (найнижча рентабельність_прогноз). Якщо запит загальний (\"що по проєктах\") — візьми 3 найкритичніші з усього портфеля, решту згадай одним рядком у Загальному висновку без I-I-A.' + String.fromCharCode(10) +
'3. Insight/Impact/Action будуй ТІЛЬКИ на основі наведених цифр вище. Якщо для конкретного висновку не вистачає даних — не вигадуй, пропусти цей пункт.' + String.fromCharCode(10) +
'4. Кожен Insight/Impact/Action — 1-2 речення, стисло. Не більше 700 символів на весь блок одного проєкту.' + String.fromCharCode(10) +
'5. Це правило застосовується ДО ВСІХ відповідей, не тільки формату Insight-Impact-Action — включно довільні питання типу \"скільки ще грошей/часу\", \"коли здамо\" тощо. Терміни з ГЛОСАРІЯ вживай однаково завжди.' + String.fromCharCode(10,10) +
'ФОРМАТ ВІДПОВІДІ (суворо, тільки HTML-теги <b>/<i>, ніякого Markdown, кольору через емодзі 🔴🟡🟢):' + String.fromCharCode(10) +
'[emoji] <b>Назва</b> (Номер)' + String.fromCharCode(10) +
'⏱ Залишок_план:Xг Факт_годин:Yг Залишок_факт:Zг Залишок_прогноз:Wг' + String.fromCharCode(10) +
'💰 Прибуток_план→Прибуток_прогноз: N → M грн  📈 Рентабельність_план→Рентабельність_прогноз: X% → Y%' + String.fromCharCode(10) +
'💡 <b>Insight:</b> [коротко, з цифрами]' + String.fromCharCode(10) +
'⚠️ <b>Impact:</b> [коротко]' + String.fromCharCode(10) +
'🎯 <b>Action:</b> [1 конкретний крок]' + String.fromCharCode(10,10) +
'Порожня лінія між проектами. У кінці — окремий рядок <b>Загальний висновок:</b> [1-2 речення по портфелю, включно зі згадкою проєктів, які не увійшли в деталі].';

const body = JSON.stringify({
  model: 'claude-sonnet-4-6',
  max_tokens: 1800,
  system: system,
  messages: [{ role: 'user', content: text }]
});

return [{ json: { body: body, chat_id: $('Telegram Trigger').item.json.message.chat.id } }];

const html = `<!DOCTYPE html>
<html lang="uk">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no">
<meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate">
<title>Archi DEMO</title>
<script src="https://telegram.org/js/telegram-web-app.js"></script>
<style>
* { box-sizing:border-box; margin:0; padding:0; }
body { font-family:-apple-system,sans-serif; background:#f5f7fa; padding:16px; color:#1e293b; }
.container { max-width:400px; margin:0 auto; }
h1 { font-size:22px; font-weight:700; margin-bottom:2px; }
