</style>
</head>
<body>
<div class="container"><div id="app"><div class="error">Завантаження…</div></div></div>
<script>
const tg = window.Telegram && window.Telegram.WebApp;
if (tg) { tg.ready(); tg.expand(); }
const DATA_BASE_URL = 'https://osbbcopilot.app.n8n.cloud/webhook/demo-archi-owner-view-data';
let DATA = null;
let state = { view: 'dashboard', group: null, idx: 0, tab: 'rent' };

function rentClass(v){ return v<0 ? 'red' : (v<0.15 ? 'orange' : 'green'); }
function rentHex(v){ return v<0 ? '#dc2626' : (v<0.15 ? '#f97316' : '#16a34a'); }
function row(label, value, cls){ return '<div class="metric"><span class="label">' + label + '</span><span class="value' + (cls?(' '+cls):'') + '">' + value + '</span></div>'; }
function hint(text){ return '<div class="hint">' + text + '</div>'; }

const TAB_DEFS = [
  {id:'rent', label:'Рентабельність'},
  {id:'profit', label:'Прибуток'},
  {id:'volume', label:'Обсяг'},
  {id:'etc', label:'ETC'},
  {id:'evm', label:'EVM'}
];

function renderDashboard(tab){
  if (tab) state.tab = tab;
  const activeTab = state.tab || 'rent';
  const v = DATA.views[activeTab];
  const tabsHtml = TAB_DEFS.map(function(t){
    return '<button class="tab' + (t.id===activeTab?' active':'') + '" data-tab="' + t.id + '">' + t.label + '</button>';
  }).join('');
  const groupsHtml = v.groups.map(function(g){
    return '<div class="group-row" data-group="' + g.id + '">' +
      '<div class="left"><span class="badge ' + g.color + '"></span>' +
      '<div><div class="name">' + g.label + '</div>' + (g.sub ? '<div class="sub">' + g.sub + '</div>' : '') + '</div></div>' +
      '<div style="display:flex;align-items:center;"><span class="count">' + g.count + '</span><span class="chev">›</span></div>' +
    '</div>';
  }).join('');

  document.getElementById('app').innerHTML =
    '<h1>📊 Портфель</h1>' +
    '<div class="sub">Archi DEMO · ' + DATA.projects.length + ' проектів</div>' +
    '<div class="tabs">' + tabsHtml + '</div>' +
    '<div class="section-title">' + v.title + '</div>' +
    '<div class="pair">' +
      '<div class="pair-card"><div class="label">' + v.heroL.label + '</div><div class="value">' + v.heroL.value + '</div></div>' +
      '<div class="pair-card"><div class="label">' + v.heroR.label + '</div><div class="value">' + v.heroR.value + '</div></div>' +
    '</div>' +
    '<div class="section-title">Групи проектів</div>' +
    '<div class="group-list">' + groupsHtml + '</div>';

  Array.prototype.forEach.call(document.querySelectorAll('.tab'), function(el){
    el.addEventListener('click', function(){ renderDashboard(this.getAttribute('data-tab')); });
  });
  Array.prototype.forEach.call(document.querySelectorAll('.group-row'), function(el){
    el.addEventListener('click', function(){ showGroup(this.getAttribute('data-group')); });
  });
  state.view = 'dashboard';
}

function renderGroup(){
  const v = DATA.views[state.tab || 'rent'];
  const list = v.groupProjects[state.group] || [];
  const def = v.groups.filter(function(g){ return g.id === state.group; })[0];
  const itemsHtml = list.length ? list.map(function(p){
    return '<div class="project-item" data-id="' + p.id + '"><span>' + p.name + ' (' + p.id + ')</span><span class="rent ' + def.color + '">' + p.value + '</span></div>';
  }).join('') : '<div style="padding:20px;text-align:center;color:#94a3b8;">Немає проектів у цій групі</div>';

  document.getElementById('app').innerHTML =
    '<button class="back-btn" onclick="showDashboard()">← Назад до портфеля</button>' +
    '<h1 style="font-size:18px;">' + (def ? def.label : '') + '</h1>' +
    '<div class="sub">' + list.length + ' проектів</div>' +
    '<div class="project-list">' + itemsHtml + '</div>';

  Array.prototype.forEach.call(document.querySelectorAll('.project-item'), function(el){
    el.addEventListener('click', function(){ showCardById(this.getAttribute('data-id')); });
  });
  state.view = 'group';
}

function renderCard(){
  const p = DATA.projects[state.idx];
  const weeklyRow = p.weeklyCostFmt
    ? row('Вартість прогресу тижня', p.weeklyCostFmt + ' / ' + p.weeklyContractFmt)
    : row('Вартість прогресу тижня', '—') + hint('Немає записів WEEKLY_LOG для цього проекту (ПМ ще не подавав тижневий звіт)');

  document.getElementById('app').innerHTML =
    '<button class="back-btn" onclick="' + (state.group ? "showGroup('" + state.group + "')" : 'showDashboard()') + '">← Назад</button>' +
    '<div class="card-top" style="border-top:4px solid ' + rentHex(p.rentForecast) + ';">' +
      '<div class="pname">' + p.name + '</div><div class="pid">' + p.id + '</div>' +
    '</div>' +
    '<div class="block">' +
      row('Контракт', p.contractFmt) +
      row('Рентабельність', p.rentPlanFmt + ' → ' + p.rentForecastFmt, rentClass(p.rentForecast)) +
      row('Прибуток', p.profitPlanFmt + ' → ' + p.profitForecastFmt) +
      row('ETC (год)', p.etcPlanFmt + ' → ' + p.etcForecastFmt) +
    '</div>' +
    '<div class="block">' +
      row('Виконані роботи', p.executedWorkFmt) +
      hint('Собівартість команди + підрядника фактично') +
      row('Оплачено замовником', p.receivedFmt) +
      hint('Гроші, що реально надійшли від клієнта') +
      row('Підписано актів', p.actsFmt) +
    '</div>' +
    '<div class="block">' +
      row('Гроші до завершення · Команда', p.moneyToCompleteTeamFmt) +
      row('Гроші до завершення · Підрядник', p.moneyToCompleteSubFmt) +
    '</div>' +
    '<div class="block">' +
      weeklyRow +
    '</div>' +
    '<div class="block">' +
      row('CPI', p.cpiFmt) +
      hint('На 1 грн витрат отримано ' + p.cpiFmt + ' грн виконаної роботи (&lt;1 — перевитрата, &gt;1 — економія)') +
      row('SPI', p.spiFmt) +
      hint('Темп виконання відносно плану (&lt;1 — відстаємо, &gt;1 — випереджаємо)') +
    '</div>' +
    '<div class="nav"><button onclick="prevProject()">← Попередній</button><button onclick="nextProject()">Наступний →</button></div>' +
    '<div class="counter">' + (state.idx+1) + ' / ' + DATA.projects.length + '</div>';
  state.view = 'card';
}

function showDashboard(){ state.group = null; renderDashboard(state.tab); }
function showGroup(g){ state.group = g; renderGroup(); }
function showCardById(id){
  const i = DATA.projects.findIndex(function(p){ return p.id === id; });
  if (i >= 0) { state.idx = i; renderCard(); }
}
function nextProject(){ state.idx = (state.idx+1) % DATA.projects.length; renderCard(); }
function prevProject(){ state.idx = (state.idx-1+DATA.projects.length) % DATA.projects.length; renderCard(); }

async function load(){
  try{
    const initData = (tg && tg.initData) ? tg.initData : '';
    if(!initData){ document.getElementById('app').innerHTML = '<div class="error">Відкрийте через кнопку в Telegram-боті.</div>'; return; }
