    profitability_forecast_pct: pct(f['Рентабельність_прогноз_pct']),
    nearest_act_date: dateOrNull(f['Найближчий_Акт_Дата']),
    nearest_act_probability: toNum(f['Найближчий_Акт_Ймовірність']),
    nearest_doc_deadline: dateOrNull(f['Найближчий_Дедлайн_Документації']),
    doc_issuance_probability: toNum(f['Ймовірність_видачі'])
  });
});
return out.map(function(r){ return { json: r }; });

const items = $input.all().map(function(i){ return i.json; });
const updated = items.filter(function(r){ return r && r.project_id; }).map(function(r){ return r.project_id; });
return [{ json: { synced_at: new Date().toISOString(), updated_count: updated.length, updated_projects: updated } }];
